import pandas as pd
import matplotlib.pyplot as plt

# 1. Read the CSV file generated by your C++ code
df = pd.read_csv("Test_h5.csv")

# 2. Create a plot with two subplots (States and Control Input)
fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(10, 8), sharex=True)

# Plot States (x0 and x1)
ax1.plot(df['k'], df['x0'], label='State 0 (x0)', color='orange', linestyle='--')
ax1.plot(df['k'], df['x1'], label='State 1 (x1)', color='blue', linewidth=2 )
ax1.plot(df['x_r'], color='red', linestyle=':', label='x0 Setpoint') # Your target
ax1.set_ylabel('State Values')
ax1.set_title('MPC System States over Time')
ax1.legend()
ax1.grid(True)

# Plot Control Input (u)
ax2.step(df['k'], df['u'], label='Control Input (u)', color='green')
ax2.axhline(y=10.0, color='red', linestyle=':', label='Max u') # From u_max
ax2.axhline(y=0.0, color='purple', linestyle=':', label='Min u') # From u_min
ax2.set_xlabel('Time Step (k)')
ax2.set_ylabel('Control Effort')
ax2.legend()
ax2.grid(True)

plt.tight_layout()
plt.show()